return {["sort"]=0,["roomList"]={{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[树林]],["roomBgm"]=[[shulin]],["permission"]=1,["fullName"]=[[树林(fb41_01)]],["enterable"]=1,["dsc"]=[[此树林位于嘉兴镇外，因为少有人烟，林中细长的小路也被杂草所覆盖，若非仔细定然难以发现。走入树林，不时能寻到几根光彩艳丽的羽毛，除此之外还有走兽的足迹。]],["down"]=[[fb41_06]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit2"]=[[npc03a]],["unit1"]=[[npc02a]],["canLeave"]=1,["id"]=[[fb41_01]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[郊外]],["permission"]=1,["enterable"]=1,["dsc"]=[[嘉兴镇的郊外，除去一条官道，两侧也只有些稀松的树木，远眺倒是有几户人烟，小河边可见几个女子正在一边说笑，一边浣纱。]],["down"]=[[fb41_08]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[郊外(fb41_02)]],["canLeave"]=1,["id"]=[[fb41_02]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb41_04]],["connectPoint"]=0,["name"]=[[乐流阁]],["roomBgm"]=[[chalou]],["permission"]=1,["enterable"]=1,["dsc"]=[[烟雨楼的乐流阁，此地所居的乃是烟雨楼的花魁娘子。一入门便是烟紫色的织锦纱帐，两侧放置紫铜香炉，案桌上有几个古董花瓶，不过都是近朝的东西，算不得名贵。]],["down"]=[[fb41_09]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["fullName"]=[[乐流阁(fb41_03)]],["canLeave"]=1,["id"]=[[fb41_03]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb41_05]],["connectPoint"]=0,["name"]=[[二楼走廊]],["roomBgm"]=[[chalou]],["permission"]=1,["left"]=[[fb41_03]],["enterable"]=1,["dsc"]=[[烟雨楼二楼的走廊，新刷的漆红色栏杆，上面的雕花虽不是出自什么名家，但也是由巧匠雕琢，以梅兰竹菊入题，俗中带雅，倒也贴合此地。]],["down"]=[[fb41_42]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["fullName"]=[[二楼走廊(fb41_04)]],["canLeave"]=1,["id"]=[[fb41_04]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[雅阁]],["roomBgm"]=[[chalou]],["permission"]=1,["left"]=[[fb41_04]],["enterable"]=1,["dsc"]=[[烟雨楼的雅阁，因为是烟雨楼的妈妈花四娘的居所，所以平日里常常大门紧闭。里面摆设甚是俗气，迎门就是两盆鲜红牡丹，左右挂花开富贵图，偶有两幅清雅的山水图也因其他的摆设显得俗气起来。]],["down"]=[[fb41_10]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["fullName"]=[[雅阁(fb41_05)]],["canLeave"]=1,["id"]=[[fb41_05]],["mapHi