[fb41_17]],["connectPoint"]=0,["name"]=[[地下密室]],["permission"]=1,["enterable"]=0,["dsc"]=[[烟雨楼的地下密室，从低矮的楼梯而下，是一间仅有两个小气窗的空地，一根烧尽的蜡烛下窜过一只老鼠。地上有不少绳索，旁边还有一条带血的鞭子。]],["fullName"]=[[地下密室(fb41_16)]],["visible"]=1,["unit4"]=[[npc32a]],["dirIndex"]=0,["unit3"]=[[npc33c]],["unit2"]=[[npc33b]],["unit1"]=[[npc33a]],["canLeave"]=1,["id"]=[[fb41_16]],["mapHide"]=0},{["operations"]={},["right"]=[[fb41_18]],["connectPoint"]=0,["enterable"]=0,["down"]=[[fb41_25]],["visible"]=1,["id"]=[[fb41_17]],["rightDown"]=[[fb41_21]],["dsc"]=[[嘉兴镇内赫赫有名的烟花之地，楼中多是以唱曲卖艺为生的姑娘，许多文人墨客都会慕名而来。烟雨楼外侧的墙壁上本雪白一片，因其艳名在外，多留下了风流客写的诗词文章。]],["permission"]=1,["fullName"]=[[烟雨楼(fb41_17)]],["mapHide"]=0,["stepMusic"]=[[jiaobu]],["canLeave"]=1,["name"]=[[烟雨楼]],["up"]=[[fb41_12]],["dirIndex"]=0,["unit3"]=[[npc20a]],["unit2"]=[[npc19a]],["unit1"]=[[npc18d]],["unit4"]=[[npc21e]],["unit5"]=[[npc79]],["left"]=[[fb41_16]]},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["right"]=[[fb41_19]],["connectPoint"]=0,["name"]=[[大厅]],["roomBgm"]=[[chalou]],["permission"]=1,["left"]=[[fb41_17]],["enterable"]=1,["dsc"]=[[烟雨楼的大厅，白日里宽敞明亮，晚上将四周的纱帐放下则旖旎无比。最中央的巨大舞台上常有姑娘在此弹唱江南小曲，近来因花魁大选，周围摆满了各色鲜花。]],["fullName"]=[[大厅(fb41_18)]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["leftUp"]=[[fb41_12]],["canLeave"]=1,["id"]=[[fb41_18]],["mapHide"]=0},{["operations"]={},["BgmDown"]=1,["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[包厢]],["roomBgm"]=[[chalou]],["permission"]=1,["left"]=[[fb41_18]],["enterable"]=1,["dsc"]=[[烟雨楼的包厢，单独的雅间，从此可以遍览厅内的各处角落，也是欣赏表演的最佳处所。嘉兴镇民常说，能进烟雨楼的非富即贵，更别说能在此处喝上一口美酒。]],["fullName"]=[[包厢(fb41_19)]],["visible"]=1,["roomBgmRule"]=1,["dirIndex"]=0,["unit2"]=[[npc77q]],["unit1"]=[[npc77r]],["canLeave"]=1,["id"]=[[fb41_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[衣庄]],["permission"]=1,["fullName"]=[[衣庄(fb41_20)]],["enterable"]=1,["dsc"]=[[江南衣庄，彩衣刺绣挂在了店铺门口，引得不少嘉兴年轻女子光顾。店里的苏绣更是一绝，据说是从苏州特意请的师傅。一架巨大的织布机堆放在店内，上面还放有未完成的绣品。]],["down"]=[[fb41_24]],["visible"]=1,["unit4"